import React, { useState, useEffect } from 'react';
import axios from 'axios';

const products = [
  { id: 1, name: 'Samsung 55" QLED TV', price: 899, originalPrice: 1299, category: 'tv', img: 'https://picsum.photos/id/1015/300/200', rating: 4.5, reviews: 1243, discount: 30, badge: 'Best Seller' },
  { id: 2, name: 'LG 65" OLED TV', price: 1299, originalPrice: 1899, category: 'tv', img: 'https://picsum.photos/id/106/300/200', rating: 4.8, reviews: 856, discount: 32, badge: 'Premium' },
  { id: 3, name: 'iPhone 15 Pro', price: 999, originalPrice: 1199, category: 'phone', img: 'https://picsum.photos/id/180/300/200', rating: 4.7, reviews: 2341, discount: 17, badge: 'New' },
  { id: 4, name: 'Samsung Galaxy S24', price: 899, originalPrice: 1099, category: 'phone', img: 'https://picsum.photos/id/201/300/200', rating: 4.4, reviews: 1567, discount: 18, badge: 'Bestseller' },
  { id: 5, name: 'MacBook Air M3 13"', price: 1099, originalPrice: 1299, category: 'computer', img: 'https://picsum.photos/id/160/300/200', rating: 4.9, reviews: 987, discount: 15, badge: 'Top Rated' },
  { id: 6, name: 'Dell XPS 13', price: 999, originalPrice: 1299, category: 'computer', img: 'https://picsum.photos/id/29/300/200', rating: 4.3, reviews: 654, discount: 23, badge: '' },
  { id: 7, name: 'Sony 75" Bravia XR TV', price: 1599, originalPrice: 2199, category: 'tv', img: 'https://picsum.photos/id/133/300/200', rating: 4.6, reviews: 432, discount: 27, badge: 'Premium' },
  { id: 8, name: 'Google Pixel 8', price: 699, originalPrice: 799, category: 'phone', img: 'https://picsum.photos/id/251/300/200', rating: 4.5, reviews: 1123, discount: 13, badge: 'Best Value' },
  { id: 9, name: 'Lenovo ThinkPad X1', price: 849, originalPrice: 1199, category: 'computer', img: 'https://picsum.photos/id/250/300/200', rating: 4.2, reviews: 567, discount: 29, badge: 'Business' },
  { id: 10, name: 'OnePlus 12 5G', price: 799, originalPrice: 899, category: 'phone', img: 'https://picsum.photos/id/160/300/200', rating: 4.4, reviews: 789, discount: 11, badge: '' },
  { id: 11, name: 'Realme 12 Pro+', price: 399, originalPrice: 499, category: 'phone', img: 'https://picsum.photos/id/201/300/200', rating: 4.1, reviews: 1567, discount: 20, badge: 'Budget' },
  { id: 12, name: 'Xiaomi 14 Pro', price: 849, originalPrice: 999, category: 'phone', img: 'https://picsum.photos/id/180/300/200', rating: 4.3, reviews: 654, discount: 15, badge: '' },
  { id: 13, name: 'TCL 43" 4K Smart TV', price: 399, originalPrice: 549, category: 'tv', img: 'https://picsum.photos/id/106/300/200', rating: 4.0, reviews: 2341, discount: 27, badge: 'Budget' },
  { id: 14, name: 'Insignia 50" 4K UHD TV', price: 449, originalPrice: 599, category: 'tv', img: 'https://picsum.photos/id/133/300/200', rating: 3.9, reviews: 876, discount: 25, badge: '' },
  { id: 15, name: 'Hisense 55" ULED TV', price: 699, originalPrice: 899, category: 'tv', img: 'https://picsum.photos/id/1015/300/200', rating: 4.2, reviews: 1234, discount: 22, badge: 'Hot Deal' },
  { id: 16, name: 'HP Pavilion 15" Laptop', price: 699, originalPrice: 899, category: 'computer', img: 'https://picsum.photos/id/29/300/200', rating: 4.1, reviews: 987, discount: 22, badge: '' },
  { id: 17, name: 'Acer Aspire 5', price: 549, originalPrice: 699, category: 'computer', img: 'https://picsum.photos/id/160/300/200', rating: 3.8, reviews: 456, discount: 21, badge: 'Budget' },
  { id: 18, name: 'ASUS VivoBook 16', price: 629, originalPrice: 799, category: 'computer', img: 'https://picsum.photos/id/250/300/200', rating: 4.0, reviews: 654, discount: 21, badge: '' }
];

const coupons = {
  'SAVE10': 10,
  'SAVE20': 20,
  'FLAT50': 50,
  'SUPER30': 30
};

function App() {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [activeTab, setActiveTab] = useState('all');
  const [currentPage, setCurrentPage] = useState('home');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginData, setLoginData] = useState({ username: '', password: '' });
  const [user, setUser] = useState(null);
  const [showOrder, setShowOrder] = useState(false);
  const [orderData, setOrderData] = useState({ address: '', payment: '' });
  const [trackingId, setTrackingId] = useState('');
  const [trackingResult, setTrackingResult] = useState(null);
  const [ticketData, setTicketData] = useState({ orderId: '', issue: '' });
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState('default');
  const [priceRange, setPriceRange] = useState({ min: 0, max: 2000 });
  const [toast, setToast] = useState(null);
  const [showBackToTop, setShowBackToTop] = useState(false);
  const [orderHistory, setOrderHistory] = useState([]);
  const [recentlyViewed, setRecentlyViewed] = useState([]);
  const [appliedCoupon, setAppliedCoupon] = useState('');
  const [couponDiscount, setCouponDiscount] = useState(0);
  const [cartQuantities, setCartQuantities] = useState({});

  // Toast notification
  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // Back to top scroll listener
  useEffect(() => {
    const handleScroll = () => setShowBackToTop(window.scrollY > 300);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Product filtering and sorting
  const getFilteredProducts = () => {
    let result = [...products];

    // Search
    if (searchQuery) {
      result = result.filter(p =>
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.category.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    // Category filter
    if (activeTab !== 'all') {
      result = result.filter(p => p.category === activeTab);
    }

    // Price range filter
    result = result.filter(p => p.price >= priceRange.min && p.price <= priceRange.max);

    // Sorting
    switch (sortBy) {
      case 'price-low':
        result.sort((a, b) => a.price - b.price);
        break;
      case 'price-high':
        result.sort((a, b) => b.price - a.price);
        break;
      case 'rating':
        result.sort((a, b) => b.rating - a.rating);
        break;
      case 'discount':
        result.sort((a, b) => b.discount - a.discount);
        break;
      default:
        break;
    }

    return result;
  };

  const filtered = getFilteredProducts();

  // Auth
  const handleLogin = () => {
    if (loginData.username && loginData.password) {
      setIsLoggedIn(true);
      setUser({ username: loginData.username });
      setCurrentPage('home');
      setLoginData({ username: '', password: '' });
      showToast('Welcome back! Login successful');
    } else {
      showToast('Please enter username and password', 'error');
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUser(null);
    setCurrentPage('login');
    setCart([]);
    setWishlist([]);
    setCartQuantities({});
    showToast('Logged out successfully');
  };

  // Cart
  const addToCart = (product) => {
    const existing = cart.findIndex(item => item.id === product.id);
    if (existing !== -1) {
      setCartQuantities(prev => ({ ...prev, [product.id]: (prev[product.id] || 1) + 1 }));
      showToast('Quantity updated in cart');
    } else {
      setCart([...cart, product]);
      setCartQuantities(prev => ({ ...prev, [product.id]: 1 }));
      showToast(`${product.name} added to cart`);
    }
  };

  const removeFromCart = (index) => {
    const product = cart[index];
    const newCart = cart.filter((_, i) => i !== index);
    setCart(newCart);
    const newQuantities = { ...cartQuantities };
    delete newQuantities[product.id];
    setCartQuantities(newQuantities);
    showToast('Item removed from cart');
  };

  const updateQuantity = (productId, newQty) => {
    if (newQty < 1) return;
    setCartQuantities(prev => ({ ...prev, [productId]: newQty }));
  };

  const total = cart.reduce((sum, item) => {
    const qty = cartQuantities[item.id] || 1;
    return sum + (item.price * qty);
  }, 0);

  const discountedTotal = Math.max(0, total - couponDiscount);

  // Wishlist
  const toggleWishlist = (product) => {
    const isInWishlist = wishlist.findIndex(item => item.id === product.id) !== -1;
    if (isInWishlist) {
      setWishlist(wishlist.filter(item => item.id !== product.id));
      showToast('Removed from wishlist');
    } else {
      setWishlist([...wishlist, product]);
      showToast('Added to wishlist');
    }
  };

  const isInWishlist = (productId) => wishlist.findIndex(item => item.id === productId) !== -1;

  // Product detail
  const openProductDetail = (product) => {
    setSelectedProduct(product);

    // Add to recently viewed
    const alreadyViewed = recentlyViewed.findIndex(p => p.id === product.id);
    if (alreadyViewed === -1) {
      const newRecent = [product, ...recentlyViewed].slice(0, 6);
      setRecentlyViewed(newRecent);
    }
  };

  // Search suggestions
  const searchSuggestions = searchQuery
    ? products.filter(p =>
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.category.toLowerCase().includes(searchQuery.toLowerCase())
      ).slice(0, 5)
    : [];

  // Coupon
  const applyCoupon = () => {
    const discount = coupons[appliedCoupon.toUpperCase()];
    if (discount) {
      const couponAmount = Math.floor((total * discount) / 100);
      setCouponDiscount(couponAmount);
      showToast(`Coupon applied! Saved $${couponAmount}`);
    } else {
      showToast('Invalid coupon code', 'error');
    }
  };

  const removeCoupon = () => {
    setAppliedCoupon('');
    setCouponDiscount(0);
    showToast('Coupon removed');
  };

  // Order
  const placeOrder = async () => {
    try {
      const orderItems = cart.map(item => ({
        ...item,
        quantity: cartQuantities[item.id] || 1
      }));

      const res = await axios.post('http://localhost:5000/order', {
        items: orderItems,
        address: orderData.address,
        payment: orderData.payment,
        total: discountedTotal,
        coupon: appliedCoupon,
        discount: couponDiscount
      });

      const newOrder = {
        id: res.data.orderId,
        date: new Date().toISOString(),
        items: orderItems,
        address: orderData.address,
        payment: orderData.payment,
        total: discountedTotal,
        status: 'Confirmed'
      };

      setOrderHistory([newOrder, ...orderHistory]);

      showToast(`Order placed! ID: ${res.data.orderId}`);
      setCart([]);
      setCartQuantities({});
      setAppliedCoupon('');
      setCouponDiscount(0);
      setShowOrder(false);
      setCurrentPage('orders');
    } catch (err) {
      showToast('Order failed', 'error');
    }
  };

  // Tracking
  const trackOrder = async () => {
    try {
      const res = await axios.get(`http://localhost:5000/tracking/${trackingId}`);
      setTrackingResult(res.data);
    } catch (err) {
      showToast('Tracking failed', 'error');
    }
  };

  // Support
  const submitTicket = async () => {
    try {
      await axios.post('http://localhost:5000/ticket', ticketData);
      showToast('Ticket submitted successfully');
      setTicketData({ orderId: '', issue: '' });
      setCurrentPage('home');
    } catch (err) {
      showToast('Ticket submission failed', 'error');
    }
  };

  // Delivery estimate
  const getDeliveryEstimate = () => {
    const days = Math.floor(Math.random() * 3) + 3;
    const date = new Date();
    date.setDate(date.getDate() + days);
    return date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
  };

  // Related products
  const getRelatedProducts = (product) => {
    return products
      .filter(p => p.category === product.category && p.id !== product.id)
      .slice(0, 4);
  };

  // Scroll to top
  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Login Screen
  if (!isLoggedIn) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' }}>
        <div style={{ background: 'white', padding: '50px', borderRadius: '12px', boxShadow: '0 20px 60px rgba(0,0,0,0.3)', width: '420px' }}>
          <div style={{ textAlign: 'center', marginBottom: '30px' }}>
            <h1 style={{ color: '#2874f0', fontSize: '36px', margin: '0 0 10px' }}>🛒 ShoppingKart</h1>
            <p style={{ color: '#666', margin: 0 }}>India's Favorite Online Shop</p>
          </div>
          <input type="text" placeholder="Username or Email" value={loginData.username} onChange={e => setLoginData({ ...loginData, username: e.target.value })} style={{ width: '100%', padding: '16px', marginBottom: '15px', fontSize: '16px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box' }} />
          <input type="password" placeholder="Password" value={loginData.password} onChange={e => setLoginData({ ...loginData, password: e.target.value })} style={{ width: '100%', padding: '16px', marginBottom: '25px', fontSize: '16px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box' }} />
          <button onClick={handleLogin} style={{ width: '100%', padding: '16px', background: '#fb641b', color: 'white', border: 'none', borderRadius: '6px', fontSize: '18px', fontWeight: '600', cursor: 'pointer', transition: 'all 0.3s' }}>Login</button>
          <p style={{ textAlign: 'center', marginTop: '20px', color: '#666', fontSize: '14px' }}>Demo: Enter any username & password</p>
        </div>
      </div>
    );
  }

  return (
    <div style={{ paddingTop: '70px' }}>
      {/* Sticky Navbar */}
      <div style={{ position: 'fixed', top: 0, left: 0, right: 0, background: '#2874f0', color: 'white', padding: '15px 30px', zIndex: 999, boxShadow: '0 2px 10px rgba(0,0,0,0.2)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', maxWidth: '1400px', margin: '0 auto' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '30px' }}>
            <h1 style={{ margin: 0, fontSize: '26px', fontWeight: 'bold', cursor: 'pointer' }} onClick={() => { setCurrentPage('home'); setActiveTab('all'); }}>🛒 ShoppingKart</h1>
            <div style={{ display: 'flex', gap: '5px' }}>
              <button onClick={() => { setCurrentPage('home'); setActiveTab('all'); }} style={{ background: 'transparent', border: 'none', color: 'white', cursor: 'pointer', padding: '8px 16px', fontSize: '14px' }}>Home</button>
              <button onClick={() => setCurrentPage('cart')} style={{ background: 'transparent', border: 'none', color: 'white', cursor: 'pointer', padding: '8px 16px', fontSize: '14px' }}>Cart {cart.length > 0 && `(${cart.length})`}</button>
              <button onClick={() => setCurrentPage('wishlist')} style={{ background: 'transparent', border: 'none', color: 'white', cursor: 'pointer', padding: '8px 16px', fontSize: '14px' }}>Wishlist {wishlist.length > 0 && `(${wishlist.length})`}</button>
              <button onClick={() => setCurrentPage('track')} style={{ background: 'transparent', border: 'none', color: 'white', cursor: 'pointer', padding: '8px 16px', fontSize: '14px' }}>Track</button>
              <button onClick={() => setCurrentPage('support')} style={{ background: 'transparent', border: 'none', color: 'white', cursor: 'pointer', padding: '8px 16px', fontSize: '14px' }}>Support</button>
              <button onClick={() => setCurrentPage('orders')} style={{ background: 'transparent', border: 'none', color: 'white', cursor: 'pointer', padding: '8px 16px', fontSize: '14px' }}>Orders</button>
            </div>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
            {recentlyViewed.length > 0 && <button onClick={() => setCurrentPage('recent')} style={{ background: 'transparent', border: 'none', color: 'white', cursor: 'pointer', fontSize: '14px' }}>Recently Viewed</button>}
            <span style={{ fontSize: '14px', background: 'rgba(255,255,255,0.2)', padding: '5px 12px', borderRadius: '20px' }}>👤 {user?.username}</span>
            <button onClick={handleLogout} style={{ background: 'white', color: '#2874f0', border: 'none', padding: '8px 16px', borderRadius: '4px', cursor: 'pointer', fontWeight: '600' }}>Logout</button>
          </div>
        </div>
      </div>

      {/* Toast Notification */}
      {toast && (
        <div style={{ position: 'fixed', top: '90px', left: '50%', transform: 'translateX(-50%)', background: toast.type === 'error' ? '#f44336' : '#4caf50', color: 'white', padding: '14px 28px', borderRadius: '30px', zIndex: 1001, boxShadow: '0 4px 15px rgba(0,0,0,0.2)', display: 'flex', alignItems: 'center', gap: '10px' }}>
          {toast.type === 'error' ? '❌' : '✅'} {toast.message}
        </div>
      )}

      {/* Hero Banner */}
      {currentPage === 'home' && !searchQuery && (
        <div style={{ background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', padding: '60px 30px', textAlign: 'center', color: 'white', marginBottom: '20px' }}>
          <h2 style={{ fontSize: '42px', margin: '0 0 15px' }}>Welcome to the Shopping Festival! 🎉</h2>
          <p style={{ fontSize: '20px', margin: '0 0 25px', opacity: 0.9 }}>Up to 50% Off on Electronics • Free Delivery on orders above $500</p>
          <div style={{ display: 'flex', justifyContent: 'center', gap: '15px', flexWrap: 'wrap' }}>
            <div style={{ background: 'rgba(255,255,255,0.2)', padding: '10px 25px', borderRadius: '30px' }}>📦 Free Shipping</div>
            <div style={{ background: 'rgba(255,255,255,0.2)', padding: '10px 25px', borderRadius: '30px' }}>🔒 Secure Payments</div>
            <div style={{ background: 'rgba(255,255,255,0.2)', padding: '10px 25px', borderRadius: '30px' }}>↩️ 30-Day Returns</div>
          </div>
        </div>
      )}

      {/* Search Bar */}
      {currentPage === 'home' && (
        <div style={{ maxWidth: '700px', margin: '0 auto 20px', padding: '0 20px', position: 'relative' }}>
          <input
            type="text"
            placeholder="🔍 Search for products, brands and more..."
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            style={{ width: '100%', padding: '16px 20px', fontSize: '16px', border: '1px solid #ddd', borderRadius: '30px', boxSizing: 'border-box', outline: 'none', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' }}
          />
          {searchSuggestions.length > 0 && (
            <div style={{ position: 'absolute', top: '55px', left: 0, right: 0, background: 'white', border: '1px solid #ddd', borderRadius: '8px', boxShadow: '0 4px 15px rgba(0,0,0,0.1)', zIndex: 100 }}>
              {searchSuggestions.map(p => (
                <div key={p.id} onClick={() => { setSearchQuery(''); openProductDetail(p); }} style={{ padding: '12px 20px', cursor: 'pointer', borderBottom: '1px solid #eee' }} onMouseEnter={e => e.target.style.background = '#f5f5f5'} onMouseLeave={e => e.target.style.background = 'white'}>
                  {p.name} - ${p.price}
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Category Navigation */}
      {currentPage === 'home' && (
        <div style={{ maxWidth: '1400px', margin: '0 auto', padding: '0 20px' }}>
          <div style={{ display: 'flex', gap: '15px', overflowX: 'auto', paddingBottom: '15px', marginBottom: '20px' }}>
            {['all', 'tv', 'phone', 'computer'].map(tab => (
              <button key={tab} onClick={() => setActiveTab(tab)} style={{
                padding: '12px 30px',
                background: activeTab === tab ? '#2874f0' : '#f5f5f5',
                color: activeTab === tab ? 'white' : '#333',
                border: 'none',
                borderRadius: '25px',
                cursor: 'pointer',
                fontWeight: '600',
                fontSize: '15px',
                whiteSpace: 'nowrap',
                transition: 'all 0.2s'
              }}>
                {tab === 'all' ? '🏠 All' : tab === 'tv' ? '📺 TVs' : tab === 'phone' ? '📱 Phones' : '💻 Computers'}
              </button>
            ))}
          </div>

          {/* Filters */}
          <div style={{ display: 'flex', gap: '15px', alignItems: 'center', marginBottom: '25px', flexWrap: 'wrap' }}>
            <select value={sortBy} onChange={e => setSortBy(e.target.value)} style={{ padding: '10px 15px', borderRadius: '6px', border: '1px solid #ddd', fontSize: '14px' }}>
              <option value="default">Sort: Relevance</option>
              <option value="price-low">Price: Low to High</option>
              <option value="price-high">Price: High to Low</option>
              <option value="rating">Rating: High to Low</option>
              <option value="discount">Biggest Discounts</option>
            </select>

            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <span style={{ fontSize: '14px', color: '#666' }}>Price Range:</span>
              <input type="number" placeholder="Min" value={priceRange.min} onChange={e => setPriceRange({ ...priceRange, min: parseInt(e.target.value) || 0 })} style={{ width: '80px', padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }} />
              <span>-</span>
              <input type="number" placeholder="Max" value={priceRange.max} onChange={e => setPriceRange({ ...priceRange, max: parseInt(e.target.value) || 2000 })} style={{ width: '80px', padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }} />
            </div>

            {(sortBy !== 'default' || priceRange.min > 0 || priceRange.max < 2000) && (
              <button onClick={() => { setSortBy('default'); setPriceRange({ min: 0, max: 2000 }); }} style={{ padding: '8px 16px', border: 'none', background: '#ff4444', color: 'white', borderRadius: '4px', cursor: 'pointer', fontSize: '13px' }}>Clear Filters</button>
            )}
          </div>
        </div>
      )}

      {/* Main Content Area */}
      <div style={{ maxWidth: '1400px', margin: '0 auto', padding: '0 20px' }}>

        {/* Home Products Grid */}
        {currentPage === 'home' && (
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(230px, 1fr))',
            gap: '25px',
            padding: '20px 0'
          }}>
            {filtered.length > 0 ? filtered.map(p => (
              <div key={p.id} style={{ background: 'white', borderRadius: '12px', overflow: 'hidden', boxShadow: '0 2px 10px rgba(0,0,0,0.08)', transition: 'all 0.3s', position: 'relative' }} onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-5px)'} onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}>
                <div style={{ position: 'relative' }}>
                  <img src={p.img} alt={p.name} onClick={() => openProductDetail(p)} style={{ width: '100%', height: '180px', objectFit: 'cover', cursor: 'pointer' }} />

                  {/* Discount Badge */}
                  {p.discount > 0 && (
                    <div style={{ position: 'absolute', top: '12px', left: '12px', background: '#388e3c', color: 'white', padding: '3px 10px', borderRadius: '4px', fontSize: '12px', fontWeight: '600' }}>%{p.discount} OFF</div>
                  )}

                  {/* Product Badge */}
                  {p.badge && (
                    <div style={{ position: 'absolute', top: '12px', right: '12px', background: p.badge === 'New' ? '#1976d2' : p.badge === 'Best Seller' ? '#f57c00' : '#7b1fa2', color: 'white', padding: '3px 10px', borderRadius: '4px', fontSize: '11px', fontWeight: '600' }}>{p.badge}</div>
                  )}

                  {/* Wishlist Heart */}
                  <button onClick={(e) => { e.stopPropagation(); toggleWishlist(p); }} style={{ position: 'absolute', bottom: '12px', right: '12px', background: 'white', border: 'none', borderRadius: '50%', width: '36px', height: '36px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 2px 8px rgba(0,0,0,0.15)' }}>
                    {isInWishlist(p.id) ? '❤️' : '🤍'}
                  </button>
                </div>

                <div style={{ padding: '16px' }} onClick={() => openProductDetail(p)}>
                  <h3 style={{ margin: '0 0 8px', fontSize: '15px', color: '#212121', fontWeight: '600', lineHeight: '1.3', cursor: 'pointer' }}>{p.name}</h3>

                  {/* Rating */}
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '8px' }}>
                    <span style={{ background: '#388e3c', color: 'white', padding: '1px 7px', borderRadius: '4px', fontSize: '13px', display: 'flex', alignItems: 'center', gap: '3px' }}>⭐ {p.rating}</span>
                    <span style={{ fontSize: '13px', color: '#878787' }}>({p.reviews.toLocaleString()})</span>
                  </div>

                  {/* Price */}
                  <div style={{ marginBottom: '12px' }}>
                    <span style={{ fontSize: '22px', fontWeight: '700', color: '#212121' }}>${p.price}</span>
                    {p.originalPrice && <span style={{ fontSize: '14px', color: '#878787', textDecoration: 'line-through', marginLeft: '8px' }}>${p.originalPrice}</span>}
                  </div>

                  <button onClick={(e) => { e.stopPropagation(); addToCart(p); }} style={{ width: '100%', background: '#ff9f00', color: 'white', border: 'none', padding: '12px', borderRadius: '4px', fontSize: '14px', fontWeight: '600', cursor: 'pointer', transition: 'background 0.2s' }} onMouseEnter={e => e.target.style.background = '#f37a00'} onMouseLeave={e => e.target.style.background = '#ff9f00'}>ADD TO CART</button>
                </div>
              </div>
            )) : <p style={{ gridColumn: '1/-1', textAlign: 'center', padding: '60px', color: '#666' }}>No products found matching your search.</p>}
          </div>
        )}

        {/* Cart Page */}
        {currentPage === 'cart' && (
          <div style={{ maxWidth: '900px', margin: '40px auto', padding: '30px', background: 'white', borderRadius: '12px', boxShadow: '0 2px 10px rgba(0,0,0,0.08)' }}>
            <h2 style={{ marginBottom: '25px' }}>🛒 Your Shopping Cart ({cart.length})</h2>
            {cart.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '60px 20px' }}>
                <p style={{ fontSize: '18px', color: '#666' }}>Your cart is empty</p>
                <button onClick={() => setCurrentPage('home')} style={{ marginTop: '20px', background: '#2874f0', color: 'white', border: 'none', padding: '14px 35px', borderRadius: '30px', cursor: 'pointer' }}>Start Shopping</button>
              </div>
            ) : (
              <>
                {cart.map((item, i) => (
                  <div key={i} style={{ display: 'flex', gap: '20px', padding: '20px 0', borderBottom: '1px solid #eee', cursor: 'pointer' }} onClick={() => openProductDetail(item)}>
                    <img src={item.img} alt={item.name} style={{ width: '100px', height: '100px', objectFit: 'cover', borderRadius: '8px' }} />
                    <div style={{ flex: 1 }}>
                      <h3 style={{ margin: '0 0 8px' }}>{item.name}</h3>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <span style={{ fontSize: '20px', fontWeight: '600' }}>${item.price}</span>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                          <button onClick={(e) => { e.stopPropagation(); updateQuantity(item.id, (cartQuantities[item.id] || 1) - 1); }} style={{ width: '30px', height: '30px', border: '1px solid #ddd', background: 'white', cursor: 'pointer', borderRadius: '4px' }}>-</button>
                          <span style={{ minWidth: '30px', textAlign: 'center' }}>{cartQuantities[item.id] || 1}</span>
                          <button onClick={(e) => { e.stopPropagation(); updateQuantity(item.id, (cartQuantities[item.id] || 1) + 1); }} style={{ width: '30px', height: '30px', border: '1px solid #ddd', background: 'white', cursor: 'pointer', borderRadius: '4px' }}>+</button>
                        </div>
                      </div>
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); removeFromCart(i); }} style={{ background: '#ff4444', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '4px', cursor: 'pointer', alignSelf: 'center' }}>Remove</button>
                  </div>
                ))}

                {/* Coupon Section */}
                <div style={{ marginTop: '25px', padding: '20px', background: '#f8f9fa', borderRadius: '8px' }}>
                  <h4 style={{ marginBottom: '12px' }}>Have a Coupon?</h4>
                  <div style={{ display: 'flex', gap: '10px' }}>
                    <input placeholder="Enter coupon code (SAVE10, SAVE20, FLAT50, SUPER30)" value={appliedCoupon} onChange={e => setAppliedCoupon(e.target.value.toUpperCase())} style={{ flex: 1, padding: '12px', border: '1px solid #ddd', borderRadius: '6px', fontSize: '14px' }} />
                    {!couponDiscount ? (
                      <button onClick={applyCoupon} style={{ padding: '12px 30px', background: '#2874f0', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Apply</button>
                    ) : (
                      <button onClick={removeCoupon} style={{ padding: '12px 30px', background: '#ff4444', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Remove</button>
                    )}
                  </div>
                  {couponDiscount > 0 && <p style={{ margin: '10px 0 0', color: '#388e3c' }}>✓ Coupon applied! Discount: ${couponDiscount}</p>}
                </div>

                <div style={{ marginTop: '25px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <div style={{ fontSize: '14px', color: '#666' }}>Estimated Delivery: {getDeliveryEstimate()}</div>
                    <div style={{ fontSize: '28px', fontWeight: '700', marginTop: '8px' }}>Total: ${discountedTotal} {couponDiscount > 0 && <span style={{ fontSize: '16px', color: '#878787', fontWeight: '400' }}>(saved ${couponDiscount})</span>}</div>
                  </div>
                  <button onClick={() => setShowOrder(true)} style={{ padding: '16px 50px', background: '#fb641b', color: 'white', border: 'none', borderRadius: '6px', fontSize: '18px', cursor: 'pointer' }}>Proceed to Checkout →</button>
                </div>
              </>
            )}
          </div>
        )}

        {/* Wishlist Page */}
        {currentPage === 'wishlist' && (
          <div style={{ maxWidth: '1400px', margin: '40px auto' }}>
            <h2 style={{ marginBottom: '25px' }}>❤️ My Wishlist ({wishlist.length})</h2>
            {wishlist.length === 0 ? <p style={{ textAlign: 'center', padding: '60px', color: '#666' }}>No items in wishlist yet</p> : (
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(230px, 1fr))', gap: '25px' }}>
                {wishlist.map(p => (
                  <div key={p.id} style={{ background: 'white', borderRadius: '12px', overflow: 'hidden', boxShadow: '0 2px 10px rgba(0,0,0,0.08)' }}>
                    <div style={{ position: 'relative' }}>
                      <img src={p.img} alt={p.name} onClick={() => openProductDetail(p)} style={{ width: '100%', height: '180px', objectFit: 'cover', cursor: 'pointer' }} />
                      <button onClick={() => toggleWishlist(p)} style={{ position: 'absolute', top: '10px', right: '10px', background: 'white', border: 'none', borderRadius: '50%', width: '36px', height: '36px', cursor: 'pointer' }}>❤️</button>
                    </div>
                    <div style={{ padding: '16px' }}>
                      <h3 style={{ margin: '0 0 8px', fontSize: '15px' }}>{p.name}</h3>
                      <p style={{ fontSize: '20px', fontWeight: '700', color: '#212121' }}>${p.price}</p>
                      <button onClick={() => addToCart(p)} style={{ width: '100%', marginTop: '12px', background: '#ff9f00', color: 'white', border: 'none', padding: '12px', borderRadius: '4px', cursor: 'pointer' }}>ADD TO CART</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Order History */}
        {currentPage === 'orders' && (
          <div style={{ maxWidth: '900px', margin: '40px auto' }}>
            <h2 style={{ marginBottom: '25px' }}>📦 Order History</h2>
            {orderHistory.length === 0 ? <p style={{ textAlign: 'center', padding: '60px', color: '#666' }}>No orders yet</p> : orderHistory.map(order => (
              <div key={order.id} style={{ background: 'white', padding: '25px', borderRadius: '12px', marginBottom: '20px', boxShadow: '0 2px 8px rgba(0,0,0,0.08)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '15px' }}>
                  <div><strong>Order #{order.id}</strong><div style={{ color: '#666', fontSize: '13px' }}>{new Date(order.date).toLocaleDateString()}</div></div>
                  <div style={{ textAlign: 'right' }}>
                    <span style={{ background: '#388e3c', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '13px' }}>{order.status}</span>
                    <div style={{ fontSize: '20px', fontWeight: '600', marginTop: '5px' }}>${order.total}</div>
                  </div>
                </div>
                {order.items.map((item, idx) => (
                  <div key={idx} style={{ padding: '10px 0', borderTop: '1px solid #eee' }}>{item.name} × {item.quantity} = ${item.price * item.quantity}</div>
                ))}
                <div style={{ marginTop: '15px', paddingTop: '15px', borderTop: '1px solid #ddd', fontSize: '14px', color: '#666' }}>📍 {order.address} • 💳 {order.payment}</div>
              </div>
            ))}
          </div>
        )}

        {/* Track Order */}
        {currentPage === 'track' && (
          <div style={{ maxWidth: '600px', margin: '60px auto', padding: '30px', background: 'white', borderRadius: '12px', boxShadow: '0 2px 10px rgba(0,0,0,0.08)' }}>
            <h2 style={{ marginBottom: '25px' }}>🚚 Track Your Order</h2>
            <input placeholder="Enter Order ID" value={trackingId} onChange={e => setTrackingId(e.target.value)} style={{ width: '100%', padding: '14px', fontSize: '16px', border: '1px solid #ddd', borderRadius: '6px', marginBottom: '15px', boxSizing: 'border-box' }} />
            <button onClick={trackOrder} style={{ width: '100%', padding: '14px', background: '#2874f0', color: 'white', border: 'none', borderRadius: '6px', fontSize: '16px', cursor: 'pointer' }}>Track Order</button>
            {trackingResult && <pre style={{ marginTop: '20px', background: '#f5f5f5', padding: '20px', borderRadius: '8px', overflow: 'auto' }}>{JSON.stringify(trackingResult, null, 2)}</pre>}
            <button onClick={() => { setCurrentPage('home'); setTrackingResult(null); setTrackingId(''); }} style={{ marginTop: '20px', width: '100%', padding: '14px', background: '#f5f5f5', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Back to Home</button>
          </div>
        )}

        {/* Support */}
        {currentPage === 'support' && (
          <div style={{ maxWidth: '600px', margin: '60px auto', padding: '30px', background: 'white', borderRadius: '12px', boxShadow: '0 2px 10px rgba(0,0,0,0.08)' }}>
            <h2 style={{ marginBottom: '25px' }}>💬 Need Help?</h2>
            <input placeholder="Order ID (optional)" value={ticketData.orderId} onChange={e => setTicketData({ ...ticketData, orderId: e.target.value })} style={{ width: '100%', padding: '14px', fontSize: '16px', border: '1px solid #ddd', borderRadius: '6px', marginBottom: '15px', boxSizing: 'border-box' }} />
            <textarea placeholder="Describe your issue..." value={ticketData.issue} onChange={e => setTicketData({ ...ticketData, issue: e.target.value })} style={{ width: '100%', padding: '14px', fontSize: '16px', border: '1px solid #ddd', borderRadius: '6px', marginBottom: '15px', minHeight: '130px', boxSizing: 'border-box', resize: 'vertical' }} />
            <button onClick={submitTicket} style={{ width: '100%', padding: '14px', background: '#2874f0', color: 'white', border: 'none', borderRadius: '6px', fontSize: '16px', cursor: 'pointer', marginBottom: '10px' }}>Submit Support Ticket</button>
            <button onClick={() => setCurrentPage('home')} style={{ width: '100%', padding: '14px', background: '#f5f5f5', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Cancel</button>
          </div>
        )}

        {/* Recently Viewed */}
        {currentPage === 'recent' && recentlyViewed.length > 0 && (
          <div style={{ maxWidth: '1400px', margin: '40px auto' }}>
            <h2 style={{ marginBottom: '25px' }}>👁️ Recently Viewed</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(230px, 1fr))', gap: '25px' }}>
              {recentlyViewed.map(p => (
                <div key={p.id} style={{ background: 'white', borderRadius: '12px', overflow: 'hidden', boxShadow: '0 2px 10px rgba(0,0,0,0.08)', cursor: 'pointer' }} onClick={() => openProductDetail(p)}>
                  <img src={p.img} alt={p.name} style={{ width: '100%', height: '180px', objectFit: 'cover' }} />
                  <div style={{ padding: '16px' }}>
                    <h3 style={{ margin: '0 0 8px', fontSize: '15px' }}>{p.name}</h3>
                    <p>${p.price}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Checkout Modal */}
      {showOrder && (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }} onClick={() => setShowOrder(false)}>
          <div style={{ background: 'white', padding: '35px', borderRadius: '12px', width: '450px' }} onClick={e => e.stopPropagation()}>
            <h2 style={{ marginBottom: '20px' }}>Checkout</h2>
            <input placeholder="Full Delivery Address" value={orderData.address} onChange={e => setOrderData({ ...orderData, address: e.target.value })} style={{ width: '100%', padding: '14px', marginBottom: '15px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box' }} />
            <input placeholder="Payment Method (Cash/Card/UPI)" value={orderData.payment} onChange={e => setOrderData({ ...orderData, payment: e.target.value })} style={{ width: '100%', padding: '14px', marginBottom: '20px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box' }} />

            <div style={{ background: '#f8f9fa', padding: '15px', borderRadius: '8px', marginBottom: '20px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}><span>Subtotal:</span><span>${total}</span></div>
              {couponDiscount > 0 && <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px', color: '#388e3c' }}><span>Discount:</span><span>-${couponDiscount}</span></div>}
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '18px', fontWeight: '700', paddingTop: '8px', borderTop: '1px solid #ddd' }}><span>Total:</span><span>${discountedTotal}</span></div>
            </div>

            <button onClick={placeOrder} style={{ width: '100%', padding: '16px', background: '#fb641b', color: 'white', border: 'none', borderRadius: '6px', fontSize: '18px', cursor: 'pointer', marginBottom: '10px' }}>Place Order</button>
            <button onClick={() => setShowOrder(false)} style={{ width: '100%', padding: '16px', background: '#f5f5f5', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Cancel</button>
          </div>
        </div>
      )}

      {/* Product Detail Modal - Flipkart Style */}
      {selectedProduct && (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '20px' }} onClick={() => setSelectedProduct(null)}>
          <div style={{ background: 'white', borderRadius: '8px', maxWidth: '1100px', width: '100%', maxHeight: '95vh', overflow: 'auto', position: 'relative' }} onClick={e => e.stopPropagation()}>
            <button onClick={() => setSelectedProduct(null)} style={{ position: 'absolute', top: '20px', right: '20px', background: 'none', border: 'none', fontSize: '32px', cursor: 'pointer', color: '#666', zIndex: 10 }}>×</button>

            <div style={{ padding: '35px', display: 'flex', gap: '50px', flexWrap: 'wrap' }}>
              {/* Image Section with Zoom Effect */}
              <div style={{ flex: '1', minWidth: '300px' }}>
                <div style={{ background: '#f8f9fa', borderRadius: '12px', overflow: 'hidden', position: 'relative' }}>
                  <img src={selectedProduct.img} alt={selectedProduct.name} style={{ width: '100%', transition: 'transform 0.3s' }} onMouseMove={e => e.target.style.transform = 'scale(1.4)'} onMouseLeave={e => e.target.style.transform = 'scale(1)'} />
                </div>
                {selectedProduct.discount > 0 && <div style={{ background: '#388e3c', color: 'white', display: 'inline-block', padding: '5px 15px', borderRadius: '4px', marginTop: '15px', fontWeight: '600' }}>Save {selectedProduct.discount}% (${selectedProduct.originalPrice - selectedProduct.price} OFF)</div>}
              </div>

              {/* Details Section */}
              <div style={{ flex: '1.2', minWidth: '300px' }}>
                {selectedProduct.badge && <div style={{ display: 'inline-block', background: '#fff3cd', color: '#856404', padding: '4px 12px', borderRadius: '4px', fontSize: '12px', fontWeight: '600', marginBottom: '10px' }}>⭐ {selectedProduct.badge.toUpperCase()}</div>}

                <h1 style={{ fontSize: '26px', fontWeight: '600', margin: '0 0 15px', color: '#212121' }}>{selectedProduct.name}</h1>

                {/* Ratings */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '20px' }}>
                  <div style={{ background: '#388e3c', color: 'white', display: 'inline-flex', alignItems: 'center', padding: '4px 10px', borderRadius: '6px', fontSize: '15px' }}>
                    ⭐ {selectedProduct.rating}
                  </div>
                  <span style={{ color: '#2874f0' }}>{selectedProduct.reviews.toLocaleString()} ratings & reviews</span>
                </div>

                {/* Price Info */}
                <div style={{ marginBottom: '25px' }}>
                  <div style={{ display: 'flex', alignItems: 'baseline', gap: '10px' }}>
                    <span style={{ fontSize: '34px', fontWeight: '700' }}>${selectedProduct.price}</span>
                    {selectedProduct.originalPrice && <span style={{ fontSize: '20px', color: '#878787', textDecoration: 'line-through' }}>${selectedProduct.originalPrice}</span>}
                  </div>
                  <div style={{ color: '#388e3c', fontSize: '15px', marginTop: '5px' }}>Inclusive of all taxes • Free Delivery</div>
                </div>

                {/* Delivery Info */}
                <div style={{ background: '#f0f0f0', padding: '14px 18px', borderRadius: '8px', marginBottom: '25px' }}>
                  <div style={{ fontWeight: '600', display: 'flex', gap: '8px', alignItems: 'center' }}>🚚 Delivery by <span style={{ color: '#388e3c' }}>{getDeliveryEstimate()}</span></div>
                </div>

                {/* Description */}
                <div style={{ marginBottom: '25px' }}>
                  <h3 style={{ fontSize: '17px', marginBottom: '12px' }}>Product Details</h3>
                  <p style={{ color: '#666', lineHeight: '1.8', fontSize: '15px' }}>
                    Premium quality {selectedProduct.name} featuring advanced technology and superior build quality.
                    Perfect for personal and professional use with excellent performance and reliability.
                    Includes manufacturer's warranty and free shipping on orders above $500.
                  </p>
                  <ul style={{ marginTop: '18px', paddingLeft: '22px', color: '#555', lineHeight: '1.9' }}>
                    <li>✓ Premium quality construction with durable materials</li>
                    <li>✓ Advanced features with latest technology</li>
                    <li>✓ 1-year comprehensive manufacturer warranty</li>
                    <li>✓ 30-day hassle-free return policy</li>
                    <li>✓ 24/7 customer support available</li>
                  </ul>
                </div>

                {/* Action Buttons */}
                <div style={{ display: 'flex', gap: '15px', flexWrap: 'wrap' }}>
                  <button onClick={() => { addToCart(selectedProduct); setSelectedProduct(null); }} style={{ flex: 1, padding: '18px 0', background: '#ff9f00', color: 'white', border: 'none', borderRadius: '6px', fontSize: '16px', fontWeight: '600', cursor: 'pointer' }}>🛒 ADD TO CART</button>
                  <button onClick={() => { toggleWishlist(selectedProduct); }} style={{ padding: '18px 24px', background: 'white', color: '#2874f0', border: '2px solid #2874f0', borderRadius: '6px', cursor: 'pointer', fontSize: '16px' }}>{isInWishlist(selectedProduct.id) ? '❤️' : '🤍'}</button>
                  <button onClick={() => setSelectedProduct(null)} style={{ flex: 1, padding: '18px 0', background: '#f5f5f5', color: '#333', border: 'none', borderRadius: '6px', fontSize: '16px', cursor: 'pointer' }}>CLOSE</button>
                </div>
              </div>
            </div>

            {/* Related Products */}
            <div style={{ padding: '25px 35px', background: '#f8f9fb', borderTop: '1px solid #eee' }}>
              <h3 style={{ marginBottom: '20px' }}>You May Also Like</h3>
              <div style={{ display: 'flex', gap: '18px', overflowX: 'auto', paddingBottom: '15px' }}>
                {getRelatedProducts(selectedProduct).map(prod => (
                  <div key={prod.id} onClick={() => { setSelectedProduct(prod); }} style={{ minWidth: '160px', background: 'white', borderRadius: '8px', overflow: 'hidden', cursor: 'pointer', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
                    <img src={prod.img} alt={prod.name} style={{ width: '100%', height: '110px', objectFit: 'cover' }} />
                    <div style={{ padding: '12px' }}>
                      <div style={{ fontSize: '13px', fontWeight: '500', marginBottom: '5px' }}>{prod.name}</div>
                      <div style={{ fontSize: '16px', fontWeight: '700' }}>${prod.price}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Back to Top Button */}
      {showBackToTop && (
        <button onClick={scrollToTop} style={{ position: 'fixed', bottom: '25px', right: '25px', width: '50px', height: '50px', borderRadius: '50%', background: '#2874f0', color: 'white', border: 'none', fontSize: '24px', cursor: 'pointer', boxShadow: '0 4px 15px rgba(0,0,0,0.3)', zIndex: 999 }} title="Back to top">↑</button>
      )}
    </div>
  );
}

export default App;
